//! Bit-exact comparison against `tests/golden.txt`, generated by `tools/noise-golden/Golden.java`
//! running on the vanilla 26.3 server jar. Point tables and label formats mirror that harness.

use std::collections::{HashMap, HashSet};

use rine_worldgen::noise::{BlendedNoise, Normalization, NormalNoise, PerlinNoise, SimplexNoise};
use rine_worldgen::random::{AnyRng, Legacy, Rng, Xoroshiro};

const GOLDEN: &str = include_str!("golden.txt");

const SEEDS: [i64; 3] = [0, 1592598566, -7];

const P3: [[f64; 3]; 33] = [
    [0.0, 0.0, 0.0],
    [0.5, 0.5, 0.5],
    [1.0, 2.0, 3.0],
    [-1.0, -2.0, -3.0],
    [-0.25, 7.5, -12.125],
    [3.7, -4.2, 5.9],
    [100.0, 64.0, -100.0],
    [100000.0, 100000.0, 100000.0],
    [-100000.0, 37.25, 200000.5],
    [0.001, -0.001, 0.0005],
    [255.9, -255.9, 256.1],
    [-511.5, 511.5, -1023.75],
    [12345.678, -98.765, 4321.0987],
    [-0.9999999, 0.9999999, 1.0000001],
    [2.5, -7.0, -0.5],
    [16.0, -16.0, 8.0],
    [-33.3, 21.7, -9.1],
    [0.333, 0.666, 0.999],
    [-123456.789, -6.5, 654321.25],
    [7.0, 7.0, 7.0],
    [-3.0, 0.0, 3.0],
    [0.1, 0.2, 0.3],
    [1e-9, -1e-9, 5.0],
    [88.8, -44.4, 22.2],
    [-0.5, -0.5, -0.5],
    [1234.5, 0.0, -1234.5],
    [50.25, -150.75, 75.125],
    [3.14159, 2.71828, 1.41421],
    [-2000.0, 1500.0, -1000.0],
    [0.75, 0.25, -0.125],
    [30000000.0, -50000000.0, 1000000000.0],
    [-30000000.5, 16777216.0, -16777217.25],
    [0.0, 0.0, 0.0],
];

const BLOCK: [[i32; 3]; 20] = [
    [0, 0, 0],
    [1, 64, 1],
    [-100, -64, 200],
    [1000, -300, -1000],
    [123456, 80, -654321],
    [-30000000, 0, 30000000],
    [5, 0, 7],
    [-17, 3, 40],
    [16, 1, -16],
    [-1, -1, -1],
    [300, 120, 300],
    [-2000, 15, 4000],
    [9, 0, 0],
    [0, 0, 9],
    [-4, 200, 5],
    [77, -20, -77],
    [2048, 63, -2048],
    [1, 2, 3],
    [-65536, 17, 65535],
    [31, 0, -31],
];

fn parse_golden() -> HashMap<String, i64> {
    let mut map = HashMap::new();
    for line in GOLDEN.lines() {
        let (label, value) = line.rsplit_once(' ').expect("golden line has a value");
        let value: i64 = value.parse().expect("golden value is an integer");
        assert!(map.insert(label.to_string(), value).is_none(), "duplicate label {label}");
    }
    map
}

struct Golden {
    map: HashMap<String, i64>,
    used: HashSet<String>,
}

impl Golden {
    fn new() -> Self {
        Self {
            map: parse_golden(),
            used: HashSet::new(),
        }
    }

    fn expect(&mut self, label: &str, actual: i64) {
        let want = *self
            .map
            .get(label)
            .unwrap_or_else(|| panic!("golden has no label {label}"));
        assert_eq!(actual, want, "bit mismatch at {label}");
        self.used.insert(label.to_string());
    }

    fn long(&mut self, label: &str, v: i64) {
        self.expect(label, v);
    }

    fn int(&mut self, label: &str, v: i32) {
        self.expect(label, v as i64);
    }

    fn double(&mut self, label: &str, v: f64) {
        self.expect(label, v.to_bits() as i64);
    }

    fn float(&mut self, label: &str, v: f32) {
        self.expect(label, v.to_bits() as i32 as i64);
    }

    fn boolean(&mut self, label: &str, v: bool) {
        self.expect(label, if v { 1 } else { 0 });
    }
}

fn make(kind: &str, seed: i64) -> AnyRng {
    if kind == "xoro" {
        AnyRng::Xoro(Xoroshiro::new(seed))
    } else {
        AnyRng::Legacy(Legacy::new(seed))
    }
}

const KINDS: [&str; 2] = ["xoro", "legacy"];

#[test]
fn random_sources_match_java() {
    let mut g = Golden::new();
    for &seed in &SEEDS {
        for kind in KINDS {
            let p = format!("{kind}.s{seed}");
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.long(&format!("{p}.long.{i}"), r.next_long());
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.int(&format!("{p}.int100.{i}"), r.next_int_bound(100));
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.int(&format!("{p}.intraw.{i}"), r.next_int());
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.int(&format!("{p}.int64.{i}"), r.next_int_bound(64));
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.int(&format!("{p}.int1000.{i}"), r.next_int_bound(1000));
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.double(&format!("{p}.double.{i}"), r.next_double());
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.float(&format!("{p}.float.{i}"), r.next_float());
            }
            let mut r = make(kind, seed);
            for i in 0..20 {
                g.boolean(&format!("{p}.bool.{i}"), r.next_bool());
            }
            let mut r = make(kind, seed);
            r.consume_count(5);
            g.long(&format!("{p}.afterconsume"), r.next_long());

            let mut r = make(kind, seed);
            let mut f1 = r.fork();
            g.long(&format!("{p}.fork.a"), f1.next_long());
            let mut f2 = r.fork();
            g.long(&format!("{p}.fork.b"), f2.next_long());

            let mut src = make(kind, seed);
            let f = src.fork_positional();
            let pts: [[i32; 3]; 7] = [
                [3, -5, 77],
                [0, 0, 0],
                [-1, -1, -1],
                [100000, 64, -100000],
                [i32::MAX, i32::MIN, 12345],
                [-7, 300, -2],
                [i32::MIN, -1, i32::MAX],
            ];
            for (k, pt) in pts.iter().enumerate() {
                let mut rr = f.at(pt[0], pt[1], pt[2]);
                g.long(&format!("{p}.at.{k}.long"), rr.next_long());
                g.int(&format!("{p}.at.{k}.int100"), rr.next_int_bound(100));
                g.double(&format!("{p}.at.{k}.double"), rr.next_double());
            }
            for name in ["minecraft:offset", "minecraft:terrain", "octave_-4", ""] {
                let mut rr = f.from_hash_of(name);
                g.long(&format!("{p}.hash[{name}].a"), rr.next_long());
                g.long(&format!("{p}.hash[{name}].b"), rr.next_long());
                g.int(&format!("{p}.hash[{name}].int100"), rr.next_int_bound(100));
            }
            let mut fs = f.from_seed(0x1234_5678_9);
            g.long(&format!("{p}.fromSeed.a"), fs.next_long());
            g.long(&format!("{p}.fromSeed.b"), fs.next_long());
        }
    }
    check_all_used(&g, |l| !is_noise_label(l) && !l.contains(".gauss.") && !l.contains(".blended."));
}

/// `nextGaussian` depends on `Math.log`. HotSpot uses an x86 intrinsic that differs from
/// `StrictMath.log` (fdlibm) and from the platform `ln`. The labels below are 1-2 ulp off and are
/// the only gaussian values allowed to differ. They must still exist in golden.txt.
const KNOWN_LOG_INTRINSIC_GAP: [&str; 2] = ["legacy.s0.gauss.12", "legacy.s0.gauss.13"];

#[test]
fn gaussian_matches_java() {
    let mut g = Golden::new();
    for &seed in &SEEDS {
        for kind in KINDS {
            let p = format!("{kind}.s{seed}");
            let mut r = make(kind, seed);
            for i in 0..20 {
                let label = format!("{p}.gauss.{i}");
                let value = r.next_gaussian();
                if KNOWN_LOG_INTRINSIC_GAP.contains(&label.as_str()) {
                    assert!(g.map.contains_key(&label), "known-gap label {label} missing from golden");
                    g.used.insert(label);
                } else {
                    g.double(&label, value);
                }
            }
        }
    }
    check_all_used(&g, |l| l.contains(".gauss."));
}

#[test]
fn perlin_simplex_normal_match_java() {
    let mut g = Golden::new();
    for &seed in &SEEDS {
        for kind in KINDS {
            let p = format!("{kind}.s{seed}");

            let mut r = make(kind, seed);
            let pn = PerlinNoise::new(&mut r);
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.perlin3.{k}"), pn.get_value(pt[0], pt[1], pt[2]));
            }
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.perlin2.{k}"), pn.get_value_2d(pt[0], pt[2]));
            }

            let mut r = make(kind, seed);
            let sn = SimplexNoise::new(&mut r);
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.simplex3.{k}"), sn.get_value_3d(pt[0], pt[1], pt[2]));
            }
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.simplex2.{k}"), sn.get_value_2d(pt[0], pt[1]));
            }

            let amps1 = [1.0, 1.0, 0.0, 1.0, 1.0];
            let n1 = NormalNoise::create_parity(-9, &amps1).create(&mut make(kind, seed));
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.normal1.3.{k}"), n1.get_value(pt[0], pt[1], pt[2]));
            }
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.normal1.2.{k}"), n1.get_value_2d(pt[0], pt[2]));
            }

            let amps2 = [1.0, 1.0, 1.0];
            let n2 = NormalNoise::create_parity(-7, &amps2).create(&mut make(kind, seed));
            for (k, pt) in P3.iter().enumerate() {
                g.float(&format!("{p}.normal2.3.{k}"), n2.get_value(pt[0], pt[1], pt[2]));
            }

            if kind == "xoro" {
                let (lo, hi) = NormalNoise::create_parity(-9, &amps1).range();
                g.float(&format!("{p}.normal1.range.min"), lo);
                g.float(&format!("{p}.normal1.range.max"), hi);
                // General constructor through the builder path (what the JSON codec produces).
                let cases: [(f64, i32, usize, Normalization, Vec<f64>); 4] = [
                    (1.0, -6, 4, Normalization::Enabled, vec![1.0, 0.5, 2.0, 1.0]),
                    (1.0, -6, 4, Normalization::Disabled, vec![1.0, 0.5, 2.0, 1.0]),
                    (1.0, -6, 4, Normalization::Legacy, vec![1.0, 0.5, 2.0, 1.0]),
                    (2.5, -3, 3, Normalization::Enabled, vec![0.0, 1.0, 1.0]),
                ];
                for (c, (amp, oct, count, norm, mods)) in cases.iter().enumerate() {
                    let nn = NormalNoise::new(*amp, *oct, *count, *norm, mods);
                    let nb = nn.create(&mut make(kind, seed));
                    let q = format!("{p}.normal.c{c}");
                    for (k, pt) in P3.iter().enumerate() {
                        g.float(&format!("{q}.3.{k}"), nb.get_value(pt[0], pt[1], pt[2]));
                    }
                    for (k, pt) in P3.iter().enumerate() {
                        g.float(&format!("{q}.2.{k}"), nb.get_value_2d(pt[0], pt[2]));
                    }
                    let (lo, hi) = nn.range();
                    g.float(&format!("{q}.range.min"), lo);
                    g.float(&format!("{q}.range.max"), hi);
                }
            }
        }
    }
    check_all_used(&g, |l| is_noise_label(l) && !l.contains(".blended."));
}

#[test]
fn blended_noise_matches_java() {
    let mut g = Golden::new();
    for &seed in &SEEDS {
        let p = format!("xoro.s{seed}");
        // RandomState: XoroshiroRandomSource(seed).forkPositional().fromHashOf("minecraft:terrain")
        let mut src = Xoroshiro::new(seed);
        let pf = src.fork_positional();
        let mut rnd = pf.from_hash_of("minecraft:terrain");
        let bn = BlendedNoise::new(&mut rnd, 0.25, 0.125, 80.0, 160.0, 8.0);
        for (k, b) in BLOCK.iter().enumerate() {
            g.float(&format!("{p}.blended.{k}"), bn.compute(b[0], b[1], b[2]));
        }
    }
    check_all_used(&g, |l| l.contains(".blended."));
}

fn is_noise_label(l: &str) -> bool {
    l.contains(".perlin") || l.contains(".simplex") || l.contains(".normal")
}

/// Every golden label in the section selected by `in_section` must have been checked by this test.
fn check_all_used(g: &Golden, in_section: impl Fn(&str) -> bool) {
    let unused: Vec<&String> = g
        .map
        .keys()
        .filter(|k| in_section(k) && !g.used.contains(*k))
        .collect();
    assert!(
        unused.is_empty(),
        "golden labels never checked by any test: {:?}",
        &unused[..unused.len().min(10)]
    );
}
